const REFERRAL_USERS = [
  {id:'scarlette', name:'Scarlette', username:'scarlette', city:'Kuala Lumpur', avatar:'s2', verified:true, active:true, kyc:true, codes:['SCAR88']},
  {id:'maul', name:'Maul', username:'maul', city:'Kuala Lumpur', avatar:'avatar', verified:true, active:true, kyc:true, codes:['MAULYOUAPP']},
  {id:'juan', name:'Juan', username:'juan', city:'Penang', avatar:'avatar', verified:true, active:true, kyc:true, codes:['JU4N7']},
  {id:'douglas', name:'Douglas', username:'douglas', city:'Kuala Lumpur', avatar:'avatar', verified:true, active:true, kyc:true, codes:[]},
  {id:'mei-ling', name:'Mei Ling', username:'mei.ling', city:'Petaling Jaya', avatar:'ca4', verified:true, active:true, kyc:true, codes:[]},
  {id:'daniel-ed', name:'Daniel Ed', username:'daniel.ed', city:'Penang', avatar:'ca1', verified:false, active:true, kyc:true, codes:[]},
  {id:'amanda', name:'Amanda Lee', username:'amanda.lee', city:'Kuala Lumpur', avatar:'avatar', verified:true, active:true, kyc:true, codes:[]},
  {id:'anisa', name:'Anisa Rahman', username:'anisa.r', city:'Shah Alam', avatar:'avatar', verified:true, active:true, kyc:true, codes:[]},
  {id:'hana', name:'Hana Lim', username:'hana.lim', city:'Petaling Jaya', avatar:'avatar', verified:false, active:true, kyc:true, codes:[]},
  {id:'rania', name:'Rania Noor', username:'rania.n', city:'Kuala Lumpur', avatar:'avatar', verified:true, active:true, kyc:true, codes:[]},
  {id:'self', name:'Elsa Japasal', username:'elsa', city:'Kuala Lumpur', avatar:'avatar', verified:true, active:true, kyc:true, self:true, codes:[]},
  {id:'pending', name:'Anwar Ismail', username:'anwar.i', city:'Kuala Lumpur', avatar:'avatar', verified:false, active:true, kyc:false, codes:[]},
  {id:'inactive', name:'Alan Tan', username:'alan.tan', city:'Penang', avatar:'avatar', verified:true, active:false, kyc:true, codes:[]},
];
const referrerById = id => REFERRAL_USERS.find(user => user.id===id) || null;
const referrerByCode = code => { const c=String(code||'').trim().replace(/^@+/,'').toUpperCase(); return REFERRAL_USERS.find(user => user.codes.includes(c)) || null; };
const referrerEligible = user => {
  const ob=S.ob||{}; const currentName=String(ob.name||'').trim().toLowerCase();
  const currentUsername=String(ob.username||'').trim().replace(/^@/,'').toLowerCase();
  return !!user && user.active && user.kyc && !user.self
    && (!currentName || user.name.toLowerCase()!==currentName)
    && (!currentUsername || user.username.toLowerCase()!==currentUsername);
};
const obRefMatches = value => {
  const query=String(value||'').trim().replace(/^@+/,'').toLowerCase();
  if (query.length<2) return [];
  const legacy=referrerByCode(query);
  if (legacy) return referrerEligible(legacy) ? [legacy] : [];
  return REFERRAL_USERS.filter(user => referrerEligible(user)
      && (user.username.toLowerCase().includes(query) || user.name.toLowerCase().includes(query)))
    .sort((a,b) => Number(b.verified)-Number(a.verified) || a.name.localeCompare(b.name))
    .slice(0,5);
};
IMG.welcomeIllus = 'data:image/svg+xml;base64,';
IMG.wlLotus = 'data:image/webp;base64,';
