function onInput(e){ const k = e.target.dataset.in; if (!k) return; const v = e.target.value;
  if (k==='email') { S.su.email=v; if(S.su.err==='email'){S.su.err=''; reRender(e);} }
  else if (k==='code') { S.su.code=v; S.su.err=''; reRender(e); }
  else if (k==='otp') { S.otp=v.replace(/\D/g,'').slice(0,6); S.otpErr=false; e.target.value=S.otp; if (S.otp.length===6) A.otpGo(); }
  else if (k==='amt') { S.pay.amt = v.replace(/[^\d.]/g,''); reRender(e); }
  else if (k==='wd') { S.wd = v.replace(/[^\d.]/g,''); reRender(e); }
  else if (k==='rfCode') { S.rfCode=v; S.rfErr=''; reRender(e); }
  else if (k==='tpAmt') { S.tp.amt = +v.replace(/[^\d.]/g,'')||0; reRender(e); }
  else if (k==='obName') { obInit().name=v.slice(0,30); obInit().nameErr=''; reRender(e); }
  else if (k==='obDob') { obInit().dob=v; render(); }
  else if (k==='obRef') { const o=obInit(); if (o.refLink || o.refSt==='ok') return; o.refQuery=v.replace(/^@+/, ''); o.ref=''; o.refSt=o.refQuery.trim()?'searching':'idle'; reRender(e); }
  else if (k==='cxT') { S.cx.title=v.slice(0,120); reRender(e); }
  else if (k==='cxD') { S.cx.desc=v.slice(0,500); reRender(e); }
  else if (k==='epName') { S.ep.name=v; }
  else if (k==='epBio') { S.ep.bio=v; }
  else if (k==='blQ') { S.blQ=v; reRender(e); }
  else if (k==='promo') { S.sub.promo=v; S.sub.promoOk=null; reRender(e); }
  else if (k==='income') { S.income = v.replace(/\D/g,''); reRender(e); }
  else if (k==='amName') S.am.name=v;
  else if (k==='amRate') { S.am.rate=v.replace(/[^\d.]/g,''); reRender(e); }
  else if (k==='amFloat') { S.am.float=v.replace(/\D/g,''); }
}
function reRender(e){ const id = e.target.id; const pos = e.target.selectionStart; render(); const n = document.getElementById(id); if (n){ n.focus(); try{ n.setSelectionRange(pos,pos); }catch(_){} } }

