    if (m.img) IMG['mxp_' + m.id] = m.img;
    MERCH[id] = {id, name:m.name, sub:'Merchant · ' + m.area, kind:'merchant', cbRate:m.cb || 0, img:m.img ? 'mxp_' + m.id : 'mer1'};
